json.dump({"mean_geom_conv":float((D_geom/D_conv).mean()),"mean_hole_conv":float((D_hole/D_conv).mean()),"max_hole_conv":float((D_hole/D_conv).max())},open('outputs/carrier_density_results.json','w'),indent=2)
